 37	    public function handle(int $playerId, int $planetId, int $unitId, int $amount): AiActionResult
 38	    {
 39	        if (!Planet::query()->whereKey($planetId)->where('user_id', $playerId)->exists()) {
 40	            return AiActionResult::rejected(AiQueueActionReason::PlanetNotOwned);
 41	        }
 42	
 43	        if ($amount < 1) {
 44	            return AiActionResult::rejected(AiQueueActionReason::NothingQueueable);
 45	        }
 46	
 47	        try {
 48	            $player = $this->playerGameStateService->advance($playerId, $planetId);
 49	
 50	            if ($player->isBanned()) {
 51	                return AiActionResult::rejected(AiQueueActionReason::PlayerBanned);
 52	            }
 53	            if ($player->isInVacationMode()) {
 54	                return AiActionResult::rejected(AiQueueActionReason::VacationMode);
 55	            }
 56	
 57	            $planet = $this->planetServiceFactory->makeForPlayer($player, $planetId, false);
 58	            $unit = ObjectService::getObjectById($unitId);
 59	            if ($unit->type !== GameObjectType::Ship && $unit->type !== GameObjectType::Defense) {
 60	                return AiActionResult::rejected(AiQueueActionReason::NotAUnit);
 61	            }
 62	
 63	            if ($unit->type === GameObjectType::Defense) {
 64	                return $this->queueDefence($player, $planetId, $unitId, $amount);
 65	            }
 66	
 67	            $this->unitQueueService->add($planet, $unitId, $amount);
 68	            $queueId = UnitQueue::query()
